const icon=(n)=>`<i data-icon="${n}" aria-hidden="true"></i>`;
function hydrateIcons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>{el.innerHTML=`<svg viewBox="0 0 24 24" aria-hidden="true">${ICONS[el.dataset.icon]||ICONS.info}</svg>`;});}
const $=(q,root=document)=>root.querySelector(q);
const $$=(q,root=document)=>Array.from(root.querySelectorAll(q));
const esc=(x)=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='orbit-crew-health-v1';
const todayKey=()=>new Date().toLocaleDateString('en-CA');
const localInput=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}T${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`;
const dayLabel=(d)=>new Date(d).toLocaleDateString('en-US',{month:'short',day:'numeric'});
const formatNum=(n,d=0)=>Number.isFinite(n)?Number(n).toFixed(d):'—';
let storageAvailable=true,toastTimer,chartMetric='hr',chartRange=7,systemSelected='cardiovascular',filterQuery='',logLimit=20;
const META={hr:{label:'Resting heart rate',short:'Heart rate',unit:'bpm',digits:0,icon:'heart',color:'#276bb4'},sys:{label:'Systolic blood pressure',short:'Blood pressure',unit:'mmHg',digits:0,icon:'pressure'},temp:{label:'Body temperature',short:'Temperature',unit:'°C',digits:1,icon:'temp'},sleep:{label:'Sleep duration',short:'Sleep',unit:'hrs',digits:1,icon:'moon'},glucose:{label:'Blood glucose',short:'Glucose',unit:'mg/dL',digits:0,icon:'drop'},mood:{label:'Mood check-in',short:'Mood',unit:'/ 5',digits:0,icon:'face'}};
Object.assign(META, INPUT_META);
const moodNames={1:'Very low',2:'Low',3:'Neutral',4:'Good',5:'Very good'};
const ROUTINES=[
 {id:'vitals',title:'Morning health check',short:'Resting indicators & symptom log',description:'Take your scheduled readings with mission approved equipment and note any symptoms.',time:'07:00',icon:'heart'},
 {id:'exercise',title:'Exercise countermeasures',short:'Follow your prescribed session',description:'Complete the aerobic and resistance work in your individual exercise prescription.',time:'09:00',icon:'activity'},
 {id:'nutrition',title:'Nutrition & hydration check',short:'Review your mission intake plan',description:'Review meals and fluids against your individual plan. Note appetite or intake changes.',time:'12:00',icon:'cup'},
 {id:'mood',title:'Wellbeing check-in',short:'Mood, workload & crew connection',description:'Record your mood, make time for a crew check-in, and note any concerns for medical review.',time:'18:00',icon:'brain'},
 {id:'sleep',title:'Sleep preparation',short:'Protect your planned rest period',description:'Review tomorrow’s schedule, follow your light routine, and prepare your sleep environment.',time:'21:00',icon:'moon'}
];
function seedDemo(){
 const hr=[65,63,64,66,62,65,64,63,65,67,64,63,65,66,64,65,63,64,66,65,64,63,65,67,66,64,65,64];
 const sleeps=[7.9,8.1,7.8,8.2,7.6,8.0,7.7,7.8,8.0,7.6,8.1,7.9,8.0,7.7,7.9,7.8,8.1,8.0,7.5,7.8,8.0,7.3,7.8,7.5,7.2,6.8,6.6,6.5];
 const entries=hr.map((h,i)=>{const d=new Date();d.setDate(d.getDate()-(27-i));d.setHours(7,0,0,0);if(d>new Date())d.setTime(Date.now()-60000);return {id:'sample-'+i,at:d.toISOString(),hr:h,sys:116+(i%5),dia:74+(i%4),temp:[36.6,36.7,36.8,36.7][i%4],sleep:sleeps[i],glucose:[89,92,94,91,90][i%5],glucoseContext:'Before meal',mood:i===27?3:4,notes:i===27?'Slept less after a schedule change. No symptoms reported.':'Routine morning check. No symptoms reported.'};});
 return {entries,checks:{[todayKey()]:['vitals','exercise','nutrition']}};
}
function defaultState(){return {version:1,mode:'demo',data:{demo:seedDemo(),personal:{entries:[],checks:{}}},settings:{mission:'Exploration 01',environment:'Lunar transit',sleepTarget:8},reminderDismissed:false};}
let state,storageNotice='',storageLocked=false;
function loadState(){
 let raw=null;try{raw=localStorage.getItem(KEY);}catch{return defaultState();}
 const stored=StateLogic.readStored(raw);if(stored.state)return stored.state;
 if(stored.damaged){try{localStorage.setItem(`${KEY}-recovery-${Date.now()}`,raw);storageNotice='Saved records could not be read, so this page started fresh. A copy of the old data was kept in this browser.';}catch{storageLocked=true;storageNotice='Saved records could not be read or copied. Saving is off so they are not overwritten.';}}
 return defaultState();
}
state=loadState();
initCrewData();
initMissionData();
function persist(){if(storageLocked){storageAvailable=false;return;}try{localStorage.setItem(KEY,JSON.stringify(state));storageAvailable=true;}catch{storageAvailable=false;toast('Browser storage is unavailable. Export your records before closing this page.');}}
window.addEventListener('storage',e=>{
 if(e.storageArea!==localStorage||e.key!==KEY)return;
 const stored=StateLogic.readStored(e.newValue);if(!stored.state)return;
 state=StateLogic.adoptState(state,stored.state);initCrewData();initMissionData();
 if($('#modal').open||$('#main form')||['crew','anatomy'].includes(currentPage()))toast('Records changed in another tab. They appear here when this page next updates.');else render();
});
function db(){return state.data[state.mode];}
function entries(){return crewRecords(activeCrewId());}
/* Shown in place of a mood score or check-in note the current viewer is not allowed to see. */
const hiddenCell=(e,key)=>e.hidden?.includes(key)?`<span class="hidden-value">${icon('lock')}Hidden</span>`:'';
function latest(key){return entries().filter(e=>Number.isFinite(e[key])).at(-1);}
function previousValues(key,days=7){const cutoff=Date.now()-days*86400000;return entries().filter(e=>new Date(e.at)>=cutoff&&Number.isFinite(e[key]));}
function checks(){return db().checks[crewCheckKey()]||[];}
function toggleCheck(id){if(!ROUTINES.some(r=>r.id===id))return;const before=factsUnlocked(),s=new Set(checks());s.has(id)?s.delete(id):s.add(id);db().checks[crewCheckKey()]=[...s];persist();render();if(factsUnlocked()>before)toast(`NASA fact ${factsUnlocked()} of ${HrpLinks.facts().length} unlocked. See it on Daily routine.`);}
/* NASA's "Did you know?" facts: one unlocks for each daily task the crew member has completed (MissionLogic.tasksCompleted). */
function factsUnlocked(){return typeof HrpLinks==='undefined'?0:Math.min(HrpLinks.facts().length,MissionLogic.tasksCompleted(db().checks,activeCrewId()));}
function factSource(f){return `<a href="${esc(f.url)}" target="_blank" rel="noopener noreferrer">${esc(f.title)}<span class="sr-only"> (NASA page, opens in a new tab)</span></a> · NASA Human Research Program`;}
function routineFacts(){const all=HrpLinks.facts(),n=factsUnlocked(),f=all[n-1];return `<div class="routine-facts"><div class="eyebrow">NASA FACTS · ${n} OF ${all.length}</div><div class="routine-facts-bar" role="img" aria-label="${n} of ${all.length} facts unlocked"><span style="width:${Math.round(n/all.length*100)}%"></span></div>${f?`<blockquote class="hrp-quote"><p>${esc(f.fact)}</p><footer>${factSource(f)}</footer></blockquote>`:'<p class="routine-facts-empty">Complete a daily task to unlock your first fact.</p>'}<p class="routine-facts-next">${n<all.length?'Each completed task unlocks the next fact from NASA’s risk pages.':`You have all ${all.length} facts.`}</p>${n?`<button class="text-button" data-facts="1">All your facts ${icon('arrowright')}</button>`:''}</div>`;}
function factsModal(){const all=HrpLinks.facts(),n=factsUnlocked();modal('Your NASA facts',`${n} of ${all.length} unlocked · From the “Did you know?” sections of NASA’s risk pages`,`<ol class="facts-list">${all.map((f,i)=>i<n?`<li><span>${String(i+1).padStart(2,'0')}</span><div><p>${esc(f.fact)}</p><small>${factSource(f)}</small></div></li>`:'').join('')}</ol>${n<all.length?`<p class="form-help">${all.length-n} more to unlock. Each completed daily task opens the next one; unticking a task locks it again.</p>`:''}`);}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3600);}
function currentPage(){const name=location.hash.slice(1).split('?')[0];return ['solar-system','overview','status','crew','log','care','model','trends','wellbeing','exercise','skin','anatomy','systems','routine','risks','supplies','earthlink','research','brief'].includes(name)?name:'overview';}
const PAGE_NAMES={'solar-system':'Solar system map',model:'Neural model',status:'Crew status',wellbeing:'Sleep & wellbeing',exercise:'Exercise',risks:'Mission health risks',supplies:'Medical supplies',earthlink:'Earth link',research:'Evidence library',skin:'Skin & wounds',care:'Health assessment',overview:'Crew overview',crew:'Astronauts',anatomy:'Anatomy lab',log:'Health log',trends:'Health trends',systems:'Body systems',routine:'Daily routine',brief:'Mission health brief'};
function button(text,action,type='',ic=''){return `<button class="button ${type}" data-action="${action}">${ic?icon(ic):''}${text}</button>`;}
function pageHeading(title,sub,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${esc(state.settings.mission).toUpperCase()} / ${esc(activeCrew().name).toUpperCase()}</div><h1>${title}</h1><p>${sub}</p></div><div class="heading-actions">${actions}</div></div>`;}
function demoNotice(){return state.mode==='demo'?`<div class="mode-notice"><span>Sample crew data. Explore the tools or start your own health log.</span><button class="text-button" data-action="personal">Use my own data ${icon('arrowright')}</button></div>`:'';}
function safetyNotice(){return `<div class="notice">${icon('info')}<p>Research prototype. Trend notes support review; they do not diagnose conditions or establish fitness for duty. Follow your crew medical officer’s instructions and mission procedures.</p></div>`;}
function sparkline(key){const v=entries().filter(e=>Number.isFinite(e[key])).slice(-12).map(e=>e[key]);if(v.length<2)return '';let min=Math.min(...v),max=Math.max(...v);if(max===min){min-=1;max+=1;}return `<svg class="sparkline" viewBox="0 0 80 28" aria-hidden="true"><path d="${v.map((n,i)=>`${i?'L':'M'}${(i*78/(v.length-1)+1).toFixed(1)},${(24-(n-min)/(max-min)*20).toFixed(1)}`).join(' ')}" fill="none" stroke="${key==='sleep'?'#ad8544':'#5d8fc1'}" stroke-width="1.4"/></svg>`;}
function metricCard(key){const m=META[key],e=latest(key),val=e?.[key];const attention=key==='sleep'&&Number.isFinite(val)&&val<state.settings.sleepTarget;const v=key==='sys'&&e?`${formatNum(e.sys)}/${formatNum(e.dia)}`:formatNum(val,m.digits);const sub=e?(key==='sleep'?`${state.settings.sleepTarget} hr planned rest target`:`Last recorded ${new Date(e.at).toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit'})}`):'Add your first measurement';return `<article class="metric-card"><div class="metric-top">${icon(m.icon)}<span>${m.short}</span><span class="metric-status ${attention?'attention':''}">${e?(attention?'REVIEW':'RECORDED'):'NO DATA'}</span></div><div class="metric-value ${key==='sys'?'bp':''}">${v}<small>${m.unit}</small></div><div class="metric-sub ${attention?'attention':''}">${attention?icon('clock'):''}${sub}</div>${sparkline(key)}</article>`;}
function chartData(){return previousValues(chartMetric,chartRange);}
function chartSVG(large=false){
 const e=chartData(),m=META[chartMetric];if(chartMetric==='mood'&&!canSeeWellbeing())return '<div class="busy-empty">Mood is hidden. Only this crew member, the crew leader and the medical officer can see it. To change who is using ORBIT, use Viewing as at the top of the screen.</div>';if(!e.length)return '<div class="busy-empty">No readings in this period. Log a health check to start a trend.</div>';
 const w=600,h=large?280:175,p={l:42,r:22,t:20,b:30};let min=Math.min(...e.map(x=>x[chartMetric])),max=Math.max(...e.map(x=>x[chartMetric]));let pad=Math.max((max-min)*.6,chartMetric==='temp'?.3:chartMetric==='sleep'?.5:chartMetric==='mood'?1:4);min=Math.max(chartMetric==='temp'?30:0,min-pad);max+=pad;if(chartMetric==='mood'){min=1;max=5;}
 const first=Date.parse(e[0].at),last=Date.parse(e.at(-1).at),start=last>first?first:first-86400000,end=last>first?last:first+86400000;
 const x=d=>p.l+(Date.parse(d)-start)/(end-start)*(w-p.l-p.r),y=v=>p.t+(1-(v-min)/(max-min))*(h-p.t-p.b);
 const path=e.map((d,i)=>`${i?'L':'M'}${x(d.at).toFixed(2)},${y(d[chartMetric]).toFixed(2)}`).join(' ');
 let grid='';for(let i=0;i<4;i++){const yy=p.t+i*(h-p.t-p.b)/3,v=max-i*(max-min)/3;grid+=`<line class="gridline" x1="${p.l}" y1="${yy}" x2="${w-p.r}" y2="${yy}"/><text x="${p.l-12}" y="${yy+3}" text-anchor="end">${formatNum(v,m.digits)}</text>`;}
 const indices=[...new Set(e.length>5?[0,Math.floor((e.length-1)/4),Math.floor((e.length-1)/2),Math.floor(3*(e.length-1)/4),e.length-1]:e.map((_,i)=>i))];
 const labels=indices.map(i=>`<text x="${x(e[i].at)}" y="${h-8}" text-anchor="middle">${dayLabel(e[i].at)}</text>`).join('');
 return `<svg class="chart" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" role="img" aria-label="${m.label}: ${e.length} readings over the past ${chartRange} days, ranging from ${formatNum(Math.min(...e.map(d=>d[chartMetric])),m.digits)} to ${formatNum(Math.max(...e.map(d=>d[chartMetric])),m.digits)} ${m.unit}">${grid}<path class="plot-area" d="${path} L${x(e.at(-1).at)},${h-p.b} L${x(e[0].at)},${h-p.b} Z"/><path class="plot-line" d="${path}"/>${e.map((d,i)=>`<circle cx="${x(d.at)}" cy="${y(d[chartMetric])}" r="3.3"/><circle class="point-hit" data-point="${i}" cx="${x(d.at)}" cy="${y(d[chartMetric])}" r="12"><title>${dayLabel(d.at)}: ${d[chartMetric]} ${m.unit}</title></circle>`).join('')}${labels}</svg>`;
}
function chartPanel(large=false){const d=chartData(),m=META[chartMetric],avg=d.length?d.reduce((a,e)=>a+e[chartMetric],0)/d.length:null;return `<section class="panel chart-card ${large?'large-chart':''}"><div class="panel-head"><div><h2>${large?m.label:'Health trends'}</h2><p>${large?'Recorded values over time':'Your indicators over the past '+chartRange+' days'}</p></div>${rangeButtons()}</div>${!large?`<div class="chart-metric-tabs" role="group" aria-label="Trend indicator">${['hr','sleep','temp'].map(k=>`<button data-chart="${k}" class="${chartMetric===k?'active':''}" aria-pressed="${chartMetric===k}">${META[k].short}</button>`).join('')}</div>`:''}<div class="chart-summary"><strong>${d.length?formatNum(d.at(-1)[chartMetric],m.digits):'—'}</strong><span>${m.unit}</span><span class="chart-average">AVG ${avg===null?'—':formatNum(avg,m.digits)} ${m.unit}</span></div><div class="chart-area">${chartSVG(large)}<div class="chart-tooltip"></div></div><div class="chart-foot"><span></span>${esc(m.label)}<a href="#${large?'log':'trends'}">${large?'View source readings':'View all trends'} →</a></div></section>`;}
function rangeButtons(){return `<div class="segmented" role="group" aria-label="Chart time range">${[7,14,30].map(d=>`<button data-range="${d}" class="${chartRange===d?'active':''}" aria-pressed="${chartRange===d}">${d}D</button>`).join('')}</div>`;}
function humanFigure(selected='cardiovascular'){
 return `<svg class="human-svg" viewBox="0 0 200 355" aria-label="Illustrative human body diagram, not a medical scan" role="img"><defs><pattern id="bodygrid" width="8" height="8" patternUnits="userSpaceOnUse"><path d="M8 0H0v8" fill="none" stroke="#a1b6cb" stroke-width=".22"/></pattern></defs><g fill="#f4f7fa" stroke="#95acc3" stroke-width="1.2"><path d="M88 55v13c-2 8-20 8-29 14-7 4-9 16-13 29l-14 45-11 40c-1 4 4 8 7 3l11-25 20-44 4 44-3 21 7 22 2 49 2 63-4 13c-2 6 7 7 11 4l12-10 3-64 7-39 7 39 3 64 12 10c4 3 13 2 11-4l-4-13 2-63 2-49 7-22-3-21 4-44 20 44 11 25c3 5 8 1 7-3l-11-40-14-45c-4-13-6-25-13-29-9-6-27-6-29-14V55Z" fill="url(#bodygrid)"/><path d="M80 26c0-13 7-21 20-21s20 8 20 21l-2 17c-1 12-11 20-18 20S83 55 82 43Z" fill="url(#bodygrid)"/><path d="M78 29c-6 0-5 12 3 13M122 29c6 0 5 12-3 13M88 68l12 11 12-11M65 85l35 17 35-17M100 80v107M66 131c19 8 49 8 68 0M65 144c20 8 50 8 70 0M64 157c21 8 51 8 72 0M62 174c24 9 52 9 76 0M61 195l39 17 39-17M100 212v12" fill="none" opacity=".6"/><path d="M80 220l3 52-2 50M120 220l-3 52 2 50M51 100l-11 51-12 34M149 100l11 51 12 34" fill="none" stroke-width="2.8" opacity=".5"/></g><g fill="none" stroke="${selected==='cardiovascular'?'#2e6daf':'#8ba6be'}" stroke-width="1.6" opacity="${selected==='cardiovascular'?'1':'.35'}"><path d="M102 106c-8-9-18-2-14 8 3 7 13 14 13 14s13-10 14-17c1-9-9-11-13-5Z" fill="#d9e7f4"/><path d="M100 79v21M106 80v21M100 128v56M106 130v55M100 158l-20 26M105 159l16 25M88 110l-22-10-15 49M115 110l19-10 15 49M100 181l-18 44-3 52M106 181l14 44 2 52"/></g><g fill="${selected==='behavioral'?'#d6e4f3':'#e9eef4'}" stroke="${selected==='behavioral'?'#2e6daf':'#9eb3c8'}" stroke-width=".9"><path d="M100 17c-7-4-15 1-14 9-3 6 1 15 7 13 3 4 7 2 7-2V17Zm0 0c7-4 15 1 14 9 3 6-1 15-7 13-3 4-7 2-7-2Z"/></g><g opacity="${selected==='immune'?'1':'.2'}" fill="#467eb4"><circle cx="76" cy="99" r="2.5"/><circle cx="125" cy="99" r="2.5"/><circle cx="91" cy="179" r="2.5"/><circle cx="111" cy="179" r="2.5"/><circle cx="106" cy="150" r="4"/></g><g fill="none" stroke="${selected==='musculoskeletal'?'#2e6daf':'#c1cfdd'}" stroke-width="2" opacity="${selected==='musculoskeletal'?'.9':'.2'}"><path d="M80 215l2 56-3 48M120 215l-2 56 3 48M68 92l-23 60-15 36M132 92l23 60 15 36M87 84h26M100 83v104M77 193h46"/><circle cx="82" cy="274" r="4"/><circle cx="118" cy="274" r="4"/></g><g fill="none" stroke="#b5c6d8" stroke-width=".6" opacity=".5"><path d="M35 55H8v27M165 55h27v27M35 329H8v-27M165 329h27v-27"/></g></svg>`;
}
function miniBody(){return `<section class="panel body-card"><div class="panel-head"><div><h2>Your body in space</h2><p>Explore the systems behind the readings</p></div><span class="body-tag">INTERACTIVE</span></div><div class="body-mini">${humanFigure()}${[['behavioral','Mind & sleep'],['cardiovascular','Cardiovascular'],['immune','Immune system'],['musculoskeletal','Bones & muscles']].map(([id,label])=>`<button class="body-hotspot hotspot-${id}" data-body="${id}">${label}</button>`).join('')}</div><div class="body-card-footer"><span>SELECT A SYSTEM TO EXPLORE</span><a href="#systems" class="text-button">View systems ${icon('arrowright')}</a></div></section>`;}
function routineList(full=false){const done=checks();return `<div class="routine-list ${full?'routine-full':''}">${ROUTINES.map(r=>`<div class="routine-item ${done.includes(r.id)?'done':''}"><button class="check-box" data-check="${r.id}" role="checkbox" aria-checked="${done.includes(r.id)}" aria-label="${esc(r.title)}">${icon('check')}</button><div class="routine-item-text">${r.title}<small>${full?r.description:r.short}</small></div><span class="routine-time">${done.includes(r.id)?'COMPLETE':(carePlan().schedule?.[r.id]||r.time)}</span></div>`).join('')}</div><div class="routine-progress" aria-label="${done.length} of 5 routine tasks complete"><div style="width:${done.length*20}%"></div></div>`;}
function observations(){const s=latest('sleep'),m=latest('mood'),notes=[];if(s&&s.sleep<state.settings.sleepTarget)notes.push({ic:'moon',title:'Sleep below your planned target',text:`Your latest entry is ${formatNum(s.sleep,1)} hours, ${formatNum(state.settings.sleepTarget-s.sleep,1)} hours below your ${state.settings.sleepTarget} hour target. Review your schedule and note persistent fatigue.`,action:'sleep-guide',label:'Review sleep guidance'});if(m&&m.mood<=2)notes.push({ic:'brain',title:'Make time for a wellbeing check',text:'You recorded a low mood. Check in with your crew medical officer, especially if the change persists or affects daily tasks.',action:'mood-guide',label:'Review wellbeing guidance'});if(!notes.length)notes.push({ic:'clipboard',title:entries().length?'Keep your record consistent':'Start with a baseline',text:entries().length?'Compare readings taken under similar conditions. A recorded value alone does not establish that you are medically well.':'Record a health check to begin your personal history. Your medical team defines your individual baseline and action limits.',action:'log',label:'Log a health check'});notes.push({ic:'document',title:'Prepare for your medical check-in',text:'Export your recorded indicators and notes for review through your approved medical communication channel.',action:'export-summary',label:'Export health summary',blue:true});return notes.slice(0,2).map(n=>`<article class="observation"><div class="observation-icon ${n.blue?'blue':''}">${icon(n.ic)}</div><div><h3>${n.title}</h3><p>${n.text}</p><button class="text-button" data-action="${n.action}">${n.label} ${icon('arrowright')}</button></div></article>`).join('');}
function overviewPage(){const latestEntry=entries().at(-1);return `${pageHeading('Crew overview',new Date().toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric',year:'numeric'}),button('<span class="export-label">Export report</span>','export-summary','','download')+button('<span class="export-label">Flight surgeon report</span>','mission-report','','document'))}<section class="hero"><img class="hero-photo" src="assets/earth-orbit.jpg" width="1200" height="800" fetchpriority="high" alt="Aurora over the curved horizon of Earth, photographed from the International Space Station"><div class="hero-content"><h2>Daily health check</h2><p><span class="hero-environment">${esc(state.settings.environment)}</span> · ${latestEntry?'Latest entry · '+esc(missionStamp(latestEntry.at)):'Record your first set of readings.'}</p><div class="hero-action">${button('Log a health check','log','','plus')}<a class="button hero-secondary" href="#care">Assess symptoms</a><a class="hero-routine" href="#routine">${checks().length}/5 routine tasks complete ${icon('arrowright')}</a></div></div><div class="hero-photo-caption">EARTH FROM THE ISS · IMAGE: NASA</div></section>${careOverviewStrip()}${missionAlertStrip()}<div class="section-label"><h2>Latest indicators</h2><span>${state.mode==='demo'?'SAMPLE DATA':latestEntry?'MANUAL ENTRY':'AWAITING FIRST ENTRY'} ${latestEntry?'· '+dayLabel(latestEntry.at).toUpperCase():''}</span></div><div class="metrics-grid">${['hr','sys','temp','sleep'].map(metricCard).join('')}</div><div class="dashboard-grid">${chartPanel()}<div class="overview-anatomy">${miniBody()}<a class="overview-atlas-link" href="#anatomy">${icon('layers')}Explore anatomy lab ${icon('arrowright')}</a></div></div><div class="lower-grid"><section class="panel"><div class="panel-head"><div><h2>Today’s routine</h2><p>A consistent rhythm for life in space</p></div><span class="check-summary">${checks().length}/5 COMPLETE</span></div>${routineList()}</section><section class="panel"><div class="panel-head"><div><h2>For your attention</h2><p>Review notes & next steps</p></div>${icon('info')}</div><div style="padding-top:8px">${observations()}</div></section></div>${safetyNotice()}<button class="health-warning-action" data-action="emergency">${icon('alert')}Urgent symptoms? View crew response guidance</button>`;}
function logPage(){const all=entries().reverse(),shown=all.filter(e=>(e.notes+' '+dayLabel(e.at)+' '+new Date(e.at).toLocaleDateString('en-US')).toLowerCase().includes(filterQuery.toLowerCase()));return `${pageHeading('Health log','A record of your measurements and observations.',button('Log health data','log','primary','plus'))}${demoNotice()}<div class="stat-strip"><div class="stat-box"><span class="eyebrow">RECORDED CHECKS</span><strong>${all.length}</strong><small>${state.mode==='demo'?'Sample health entries':'Manual health entries'}</small></div><div class="stat-box"><span class="eyebrow">LATEST CHECK</span><strong style="font-size:22px">${all.length?dayLabel(all[0].at):'—'}</strong><small>${all.length?new Date(all[0].at).toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit'}):'No records yet'}</small></div><div class="stat-box"><span class="eyebrow">RECORD LOCATION</span><strong style="font-size:22px">Local</strong><small>This browser, on this device</small></div></div><section class="panel content-panel"><div class="filters"><label for="log-search">Filter records</label><input id="log-search" class="field-input" type="search" placeholder="Search dates or notes…" value="${esc(filterQuery)}"><button class="button small" data-action="export-csv" style="margin-left:auto">${icon('download')}Export CSV</button></div>${all.length?`<p class="workspace-table-hint">Scroll across the table to see all indicators.</p><div class="table-wrap" tabindex="0" aria-label="Health measurements. Scroll horizontally to view all columns."><table class="data-table"><thead><tr><th>DATE / LOCAL TIME</th><th>HR<br>bpm</th><th>BP<br>mmHg</th><th>TEMP<br>°C</th><th>SLEEP<br>hrs</th><th>GLUCOSE<br>mg/dL</th><th>MOOD<br>/ 5</th><th>NOTES</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody>${shown.slice(0,logLimit).map(e=>`<tr><td><button class="text-button" data-entry="${esc(e.id)}">${dayLabel(e.at)}</button><span class="small-sub">${new Date(e.at).toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit'})}</span></td><td>${formatNum(e.hr)}</td><td>${Number.isFinite(e.sys)?formatNum(e.sys)+'/'+formatNum(e.dia):'—'}</td><td>${formatNum(e.temp,1)}</td><td>${formatNum(e.sleep,1)}</td><td>${formatNum(e.glucose)}<span class="small-sub">${esc(e.glucoseContext||'')}</span></td><td>${hiddenCell(e,'mood')||formatNum(e.mood)}</td><td class="log-note" title="${esc(e.notes)}">${hiddenCell(e,'notes')||esc(e.notes)||'—'}</td><td><button class="table-delete" data-delete="${esc(e.id)}" aria-label="Delete record from ${dayLabel(e.at)}">${icon('trash')}</button></td></tr>`).join('')}</tbody></table></div>${!shown.length?'<div class="empty-state" style="padding:35px">No records match your search.</div>':''}${shown.length>logLimit?`<button class="text-button" style="margin-top:20px" data-action="more-log">Show more records</button>`:''}`:emptyState()} </section><div class="notice">${icon('lock')}<p>Records stay in this browser. Clearing browser storage removes them. Use CSV or the health summary export to keep a copy; no data is sent to a medical team. The optional Crew assistant receives only the records you explicitly review and share.</p></div>`;}
function emptyState(){return `<div class="empty-state">${icon('clipboard')}<h2>Your health record starts here.</h2><p>Add a measurement, sleep entry, or mood check-in.</p>${button('Log a health check','log','primary','plus')}</div>`;}
function trendsPage(){const d=chartData(),m=META[chartMetric],values=d.map(e=>e[chartMetric]);return `${pageHeading('Health trends','See how your indicators change over time.',button('<span class="export-label">Export data</span>','export-csv','','download'))}${demoNotice()}<div class="trends-top"><label for="trend-metric" class="eyebrow">INDICATOR</label><select class="field-input trends-select" id="trend-metric">${Object.entries(META).map(([k,v])=>`<option value="${k}" ${k===chartMetric?'selected':''}>${v.label}</option>`).join('')}</select><span style="margin-left:auto" class="eyebrow">${state.mode==='demo'?'SAMPLE HISTORY':'YOUR RECORDS'}</span></div>${chartPanel(true)}${missionTrendPanel()}<div class="trends-grid"><article class="panel insight-card"><h3>LOWEST RECORDED</h3><strong>${values.length?formatNum(Math.min(...values),m.digits):'—'} <small style="font-size:12px;color:var(--muted)">${m.unit}</small></strong><p>Minimum in the selected ${chartRange} day period.</p></article><article class="panel insight-card"><h3>HIGHEST RECORDED</h3><strong>${values.length?formatNum(Math.max(...values),m.digits):'—'} <small style="font-size:12px;color:var(--muted)">${m.unit}</small></strong><p>Maximum in the selected ${chartRange} day period.</p></article><article class="panel insight-card"><h3>DATA POINTS</h3><strong>${values.length}</strong><p>${m.label} readings in this period.</p></article></div><div class="notice">${icon('info')}<p>These charts show recorded values, not a clinical risk score. Compare measurements taken with the same method, context, and equipment. Your medical team defines your personal action limits.</p></div>`;}
const SYSTEMS={
 cardiovascular:{title:'Cardiovascular system',short:'Cardiovascular',icon:'heart',number:'01',description:'Changes in gravity affect blood distribution and the work your heart does. Blood pressure and resting heart rate give your medical team context for changes over time.',track:['Resting heart rate and blood pressure','Dizziness, palpitations, chest symptoms','Exercise tolerance and unusual fatigue'],action:'Take readings under consistent conditions with mission approved equipment. Record symptoms and your activity before the measurement. Report unexpected or persistent changes through your crew medical protocol.',limit:'Heart rate and blood pressure alone cannot rule out a cardiovascular event.',metrics:['hr','sys']},
 musculoskeletal:{title:'Bones & muscles',short:'Bones & muscles',icon:'bone',number:'02',description:'Reduced mechanical loading in microgravity can weaken bones and muscles. Aerobic and resistance exercise form part of the countermeasure plan.',track:['Completion of prescribed exercise sessions','Pain, mobility changes, and exercise tolerance','Scheduled fitness evaluations'],action:'Follow your individual exercise and nutrition prescription. Document pain or reduced function and review it with your crew medical officer.',limit:'This app cannot estimate bone density or muscle loss from routine vital signs.',metrics:[]},
 immune:{title:'Immune system',short:'Immune system',icon:'shield',number:'03',description:'Spaceflight can alter immune responses. Shared, closed living quarters also change how crews encounter microbes.',track:['Body temperature with the same method','New symptoms and their onset','Changes in fatigue, appetite, or skin'],action:'Record symptoms alongside your temperature. Follow habitat hygiene procedures and report new or worsening symptoms to the crew medical officer.',limit:'A temperature reading cannot diagnose infection or measure immune function.',metrics:['temp']},
 behavioral:{title:'Mind & sleep',short:'Mind & sleep',icon:'brain',number:'04',description:'Isolation, confinement, workload, and changing light cycles can affect mood, sleep, and alertness. A regular record can help identify a change worth discussing.',track:['Sleep duration and perceived rest','Mood and changes in daily function','Workload, schedule changes, and crew connection'],action:'Protect your planned sleep period and follow your light schedule. Make time for private medical check-ins and crew contact. Report persistent mood changes or fatigue that affects tasks.',limit:'A five point mood entry is a personal journal measure, not a validated mental health screen.',metrics:['sleep','mood']},
 nutrition:{title:'Nutrition & metabolism',short:'Nutrition & metabolism',icon:'drop',number:'05',description:'Food and fluid intake support performance, recovery, and health in space. Record glucose only when your individual medical plan calls for it.',track:['Meal and fluid intake against your plan','Appetite changes or difficulty eating','Prescribed glucose readings and meal context'],action:'Follow your individualized meal and hydration plan. Record the context of any glucose measurement and use your prescribed response protocol for unexpected results.',limit:'This prototype does not interpret glucose results or recommend medication changes.',metrics:['glucose']}
};
const SPACE_BODY_EFFECTS={
 cardiovascular:['Fluid shifts toward the head can cause facial puffiness and congestion.','Circulation adapts to reduced weight-bearing; standing after landing can bring dizziness.'],
 musculoskeletal:['Bones and postural muscles carry less load when floating, so they can lose strength over time.','Resistance exercise supplies mechanical loading that ordinary floating does not.'],
 immune:['Spaceflight can change immune regulation; microgravity is one factor alongside stress and the habitat environment.','These changes cannot be measured from how weightless you feel.'],
 behavioral:['The inner ear loses its familiar gravity cue, which can cause disorientation or space motion sickness.','The brain adapts to new movement cues; returning to gravity requires readjustment.'],
 nutrition:['Fluid redistribution changes fluid balance; thirst alone does not describe where fluid is distributed.','Adequate food and planned hydration support exercise and adaptation.']
};
function spaceForceAnimation(type){
 const person=`<circle cx="0" cy="-9" r="6" fill="#e7f2ff"/><path d="M0-2V15M-9 5 0 1 9 5M0 15-7 24M0 15 7 24" fill="none" stroke="#e7f2ff" stroke-width="4" stroke-linecap="round"/>`;
 const scenes={
 orbit:{title:'Station and astronaut orbit Earth together',caption:'You and the station share the same free fall.',drawing:`<circle cx="160" cy="90" r="27" fill="#327db4"/><path d="M147 70 160 76 155 89 171 96 166 112" fill="none" stroke="#78cbb4" stroke-width="9"/><circle cx="160" cy="90" r="65" class="force-track"/><g class="force-revolve"><g transform="translate(225 90)"><rect x="-22" y="-20" width="44" height="44" rx="8" class="force-cabin"/><g transform="scale(.65)">${person}</g></g></g>`},
 centripetal:{title:'An inward arrow follows an orbiting station',caption:'Gravity points inward as the orbital path curves.',drawing:`<circle cx="160" cy="90" r="25" fill="#327db4"/><circle cx="160" cy="90" r="65" class="force-track"/><g class="force-revolve"><circle cx="225" cy="90" r="9" fill="#e7f2ff"/><path d="M210 90H188M194 84 188 90 194 96" class="force-arrow"/></g>`},
 rotation:{title:'A rotating habitat carries a person around its rim',caption:'The floor pushes your feet toward the center.',drawing:`<circle cx="160" cy="90" r="4" fill="#8fbedc"/><g class="force-revolve force-wheel"><circle cx="160" cy="90" r="66" fill="none" stroke="#7196b7" stroke-width="9"/><path d="M94 90H226M160 24V156" stroke="#385773" stroke-width="2"/><g transform="translate(160 126) scale(.7)">${person}</g><path d="M184 144V114M178 120 184 114 190 120" class="force-arrow"/></g>`},
 push:{title:'An astronaut pushes off one wall and coasts to the other',caption:'Push off → coast → contact → return. No force is needed to keep coasting.',drawing:`<path d="M60 40V140M260 40V140" stroke="#7196b7" stroke-width="8"/><path d="M77 90H243" class="force-track"/><g class="force-coast"><g transform="translate(82 82)">${person}</g></g><path d="M113 124H148M140 118 148 124 140 130" class="force-arrow"/>`}
 };
 const scene=scenes[type];return `<figure class="force-animation"><svg viewBox="0 0 320 180" role="img" aria-label="${scene.title}">${scene.drawing}</svg><figcaption>${scene.caption}</figcaption></figure>`;
}
function attachSpaceAnimations(){document.querySelectorAll('.space-forces').forEach(panel=>{const toggle=panel.querySelector('[data-force-motion]');if(!toggle)return;toggle.addEventListener('click',()=>{const paused=panel.classList.toggle('force-paused');toggle.setAttribute('aria-pressed',String(paused));toggle.textContent=paused?'Play animations':'Pause animations';});});}
function spaceForcesPanel(){return `<section class="panel space-forces" aria-labelledby="space-forces-title"><div class="eyebrow">LIVING ON A SPACE STATION</div><h2 id="space-forces-title">What forces is your body experiencing?</h2><button type="button" class="text-button force-motion-toggle" data-force-motion aria-pressed="false">Pause animations</button><p class="force-model-note">Illustrations of motion, not to scale. Rotating habitat shown as a concept.</p><div class="space-force-grid"><article><h3>Gravity & orbital free fall</h3>${spaceForceAnimation('orbit')}<ul><li>Earth’s gravity still pulls on you in orbit. You and the station fall around Earth together, creating the sensation of weightlessness.</li><li>Without a floor continually supporting your weight, your body experiences very little sustained loading.</li></ul></article><article><h3>Centripetal acceleration</h3>${spaceForceAnimation('centripetal')}<ul><li>Gravity provides the inward acceleration that curves the station’s path around Earth. “Centripetal” describes that inward direction, rather than an extra force.</li><li>Because you share the station’s free fall, orbital motion does not pin you against its walls.</li></ul></article><article><h3>A rotating station</h3>${spaceForceAnimation('rotation')}<ul><li>A habitat designed to spin could press its floor against your feet, providing the inward force needed to move you in a circle. You would feel an apparent outward weight.</li><li>That is artificial gravity by rotation. It differs from ordinary floating aboard the ISS.</li></ul></article><article><h3>Pushes & exercise loads</h3>${spaceForceAnimation('push')}<ul><li>Your mass and inertia remain: pushing off a handrail starts you moving, and contact is needed to stop or turn.</li><li>Exercise equipment and restraints apply forces to your body even while you are otherwise weightless.</li></ul></article></div><p class="detail-source">Learn more: <a href="https://science.nasa.gov/learn/basics-of-space-flight/chapter3-4/" target="_blank" rel="noopener noreferrer">NASA: gravity & orbital mechanics ↗</a> · <a href="https://ntrs.nasa.gov/api/citations/20070001008/downloads/20070001008.pdf" target="_blank" rel="noopener noreferrer">NASA: artificial gravity (PDF) ↗</a></p></section>`;}
function bodyFieldAnimation(type){
 const tissue='<rect x="111" y="38" width="98" height="108" rx="38" fill="#203e59" stroke="#8fbfdf" stroke-width="2"/>';
 const wave='<path d="M30 90H75L85 77 96 105 108 55 121 120 135 90H290" fill="none" stroke="#61e6ff" stroke-width="3"/>';
 const scenes={
 signal:{title:'An electrical signal travels along a nerve toward muscle',caption:'A traveling signal coordinates activity; this is not a moving electron in a wire.',drawing:'<text x="30" y="40">NERVE</text><text x="231" y="40">MUSCLE</text><path d="M30 90H240" stroke="#597f9d" stroke-width="12"/><path d="M30 90H240" class="field-flow"/><rect x="244" y="63" width="48" height="54" rx="18" fill="#d98c89" class="field-response"/><path d="M35 120H220M210 114 220 120 210 126" class="force-arrow"/>'},
 charge:{title:'Charges redistribute at the surface of a body in an electric field',caption:'Surface charge redistribution shown schematically; motion is exaggerated.',drawing:tissue+'<path d="M25 65H100M25 110H100M220 65H295M220 110H295" class="field-flow"/><g class="field-charge"><text x="120" y="75">−</text><text x="120" y="111">−</text><text x="185" y="75">+</text><text x="185" y="111">+</text></g>'},
 induction:{title:'A changing magnetic field induces a circulating electric field in tissue',caption:'Changing magnetic flux can induce circulating currents in tissue.',drawing:tissue+'<g class="field-flux" stroke="#61e6ff" stroke-width="2">'+[130,160,190].map(x=>[63,90,117].map(y=>`<path d="M${x-4} ${y-4}l8 8m-8 0l8-8"/>`).join('')).join('')+'</g><ellipse cx="160" cy="92" rx="72" ry="38" class="field-flow"/><text x="25" y="28">× MAGNETIC FIELD INTO PAGE</text>'},
 frequency:{title:'Slow and fast oscillations illustrate different field frequencies',caption:'Frequency changes the interaction. Wave height here does not indicate exposure.',drawing:'<text x="25" y="30">LOW FREQUENCY</text><path d="M25 60Q60 15 95 60T165 60T235 60T305 60" class="field-flow"/><text x="25" y="110">HIGHER FREQUENCY</text>'},
 device:{title:'A nearby magnet can change an implanted device operating mode',caption:'Device interference is different from direct stimulation of heart tissue.',drawing:'<g class="field-magnet"><rect x="40" y="60" width="55" height="25" rx="4" fill="#d98c89"/><rect x="40" y="85" width="55" height="25" rx="4" fill="#61e6ff"/><text x="52" y="78">N</text><text x="52" y="103">S</text></g><path d="M110 70Q160 40 200 70M110 110Q160 140 200 110" class="field-flow"/><rect x="210" y="57" width="65" height="68" rx="12" class="force-cabin"/><circle cx="242" cy="79" r="5" fill="#ffcf68" class="field-response"/><path d="M222 104h9l5-9 8 16 7-7h13" stroke="#61e6ff" fill="none" stroke-width="2"/>'},
 radiation:{title:'An energetic particle crosses a schematic cell',caption:'Particle radiation can damage cells; this is separate from the field animations.',drawing:'<circle cx="205" cy="90" r="47" fill="#203e59" stroke="#8fbfdf" stroke-width="2"/><circle cx="205" cy="90" r="20" fill="#57758e"/><path d="M25 90H285" stroke="#a38266" stroke-dasharray="4 6"/><circle cx="150" cy="90" r="5" fill="#ffcf68" class="field-particle"/><text x="25" y="30">ENERGETIC PARTICLE</text><text x="180" y="156">CELL</text>'}
 };
 scenes.frequency.drawing+='<path d="M25 140'+Array.from({length:14},(_,i)=>`q10 ${i%2?32:-32} 20 0`).join('')+'" class="field-flow"/>';
 const item=scenes[type];return `<figure class="force-animation body-field-animation"><svg viewBox="0 0 320 180" role="img" aria-label="${item.title}">${item.drawing}</svg><figcaption>${item.caption}</figcaption></figure>`;
}
function electromagneticBodyPanel(){return `<section class="panel space-forces" aria-labelledby="body-fields-title"><div class="eyebrow">FIELDS & THE BODY’S ELECTRICAL SYSTEM</div><h2 id="body-fields-title">How electric and magnetic fields interact with you</h2><button type="button" class="text-button force-motion-toggle" data-force-motion aria-pressed="false">Pause animations</button><p class="force-model-note">Concept animations, not to scale. Motion does not represent measured field strength or exposure.</p><p>Effects depend on field strength, frequency, exposure time, and how energy couples into the body. The colored fields in the <a href="#solar-system">Solar system map</a> illustrate geometry; they do not calculate a crew member’s exposure.</p><div class="space-force-grid"><article><h3>Your body already uses electricity</h3>${bodyFieldAnimation('signal')}<p>Nerves, muscles, and the heart use electrical signals produced by charged particles called ions. These signals coordinate sensation, movement, and heartbeat. An ECG records the heart’s electrical activity.</p></article><article><h3>Electric fields: charges and currents</h3>${bodyFieldAnimation('charge')}<p>Electric fields act on charges. Low-frequency external fields redistribute charge at the body’s surface and can produce currents. This exposure differs from directly touching an energized conductor, where current can flow through the body.</p></article><article><h3>Magnetic fields: changing fields matter</h3>${bodyFieldAnimation('induction')}<p>Time-varying magnetic fields can induce electric fields and currents inside tissue. If sufficiently strong, these currents can stimulate nerves and muscles. A steady magnetic field and a rapidly changing field do not produce identical effects.</p></article><article><h3>Frequency changes the interaction</h3>${bodyFieldAnimation('frequency')}<p>At low frequencies, induced nerve and muscle stimulation is a concern at high exposures. At radiofrequencies, sufficient absorbed energy heats tissue. Ordinary low-level exposure is not equivalent to these high-exposure conditions.</p><p class="detail-source">Mechanisms: <a href="https://www.who.int/news-room/questions-and-answers/item/radiation-electromagnetic-fields" target="_blank" rel="noopener noreferrer">WHO: electromagnetic fields ↗</a></p></article><article><h3>Heart devices and electronic equipment</h3>${bodyFieldAnimation('device')}<p>A magnet can activate a pacemaker’s or defibrillator’s special operating mode. This is interference with the device; it does not mean the magnet directly changed the heart’s natural electrical signals. The FDA recommends keeping phones and smartwatches at least 6 inches (15 cm) from implanted medical devices and following device-specific instructions.</p><p>For spacecraft electronics, energetic particles can cause a single-event upset or permanent damage; accumulated radiation can degrade components. Engineering protection requires radiation testing and appropriate component and system design.</p><p class="detail-source"><a href="https://www.fda.gov/radiation-emitting-products/cell-phones/magnets-cell-phones-and-smart-watches-may-affect-pacemakers-and-other-implanted-medical-devices" target="_blank" rel="noopener noreferrer">FDA: magnets & implants ↗</a> · <a href="https://www.nasa.gov/reference/jsc-radiation/" target="_blank" rel="noopener noreferrer">NASA: radiation & electronics ↗</a></p></article><article><h3>Space radiation is a separate exposure</h3>${bodyFieldAnimation('radiation')}<p>High-energy solar particles and galactic cosmic rays can damage cells and DNA. NASA studies risks including cancer and effects on the nervous and cardiovascular systems. These particle-radiation risks cannot be inferred from the strength or appearance of a planet’s illustrated electric or magnetic field.</p><p>Follow mission radiation monitoring and shelter procedures. Routine heart-rate, mood, or sleep entries in this app cannot measure field exposure or radiation dose.</p><p class="detail-source"><a href="https://www.nasa.gov/hrp/hazard-space-radiation/" target="_blank" rel="noopener noreferrer">NASA: space radiation & human health ↗</a></p></article></div></section>`;}
function systemsPage(){const s=SYSTEMS[systemSelected];return `${pageHeading('Your body in space','Understand the systems behind your daily health record.')}${spaceForcesPanel()}${electromagneticBodyPanel()}<div class="systems-layout"><nav class="system-nav" aria-label="Body systems"><div class="eyebrow">EXPLORE A SYSTEM</div>${Object.entries(SYSTEMS).map(([id,x])=>`<button data-system="${id}" class="${id===systemSelected?'active':''}" aria-pressed="${id===systemSelected}">${icon(x.icon)}${x.short}</button>`).join('')}</nav><div class="systems-figure">${humanFigure(systemSelected)}<div class="eyebrow">${s.short.toUpperCase()} / ILLUSTRATIVE VIEW</div></div><article class="system-detail"><div class="system-num">SYSTEM ${s.number} / HUMAN HEALTH</div><h2>${s.title}</h2><p>${s.description}</p><div class="detail-block"><h3>WHAT YOUR BODY EXPERIENCES IN SPACE</h3><ul>${SPACE_BODY_EFFECTS[systemSelected].map(t=>`<li>${t}</li>`).join('')}</ul><p class="detail-source">Educational overview: <a href="https://www.nasa.gov/humans-in-space/the-human-body-in-space/" target="_blank" rel="noopener noreferrer">NASA: the human body in space ↗</a></p></div>${s.metrics.length?`<div class="system-readings">${s.metrics.map(k=>{const m=META[k],e=latest(k);return `<div class="system-reading"><span>${m.short.toUpperCase()}</span><strong>${e?formatNum(e[k],m.digits):'—'}</strong> <small>${m.unit}</small></div>`;}).join('')}</div>`:''}${HrpLinks.forSystem(systemSelected).length?`<div class="detail-block hrp-detail"><h3>NASA RISKS FOR THIS SYSTEM</h3>${hrpRiskList(HrpLinks.forSystem(systemSelected),'summary')}</div>`:''}${csaBlock(HrpLinks.csaForSystem(systemSelected))?`<div class="detail-block hrp-detail"><h3>CANADIAN SPACE AGENCY</h3>${csaBlock(HrpLinks.csaForSystem(systemSelected))}</div>`:''}<div class="detail-block"><h3>WHAT TO TRACK</h3><ul>${s.track.map(t=>`<li>${t}</li>`).join('')}</ul></div><div class="detail-block"><h3>CREW ACTION</h3><p>${s.action}</p></div><div class="detail-block"><h3>ASSESSMENT LIMIT</h3><p>${s.limit}</p></div><div class="detail-source">Based on NASA Human Research Program resources. <a href="#brief">View mission brief →</a></div></article></div>${safetyNotice()}`;}
function routinePage(){const n=checks().length;return `${pageHeading('Daily routine','Your daily health tasks, in one place.',button('Log health data','log','','plus'))}${demoNotice()}<div class="routine-page-grid"><section class="panel"><div class="panel-head"><div><h2>${new Date().toLocaleDateString('en-US',{weekday:'long',month:'short',day:'numeric'})}</h2><p>Individual schedule · Local device time</p></div><span class="check-summary">${n}/5 COMPLETE</span></div>${routineList(true)}<div class="notice" style="margin:0 21px 21px">${icon('clock')}<p>The list starts fresh each local day. Checkmarks record completion; they do not verify that a clinical protocol was performed.</p></div></section><aside class="panel routine-side"><div class="progress-ring"><svg viewBox="0 0 120 120" aria-hidden="true"><circle cx="60" cy="60" r="52"/><circle class="progress-ring-fill" cx="60" cy="60" r="52" stroke-dasharray="326.73" stroke-dashoffset="${326.73*(1-n/5)}"/></svg><strong>${n}/5</strong></div><h2>${n===5?'Daily routine complete.':'Keep a steady routine.'}</h2><p>${n===5?'Your completion record is saved for today. Return tomorrow for a fresh checklist.':'A consistent routine helps you notice changes. Use your actual mission schedule and individual prescriptions to guide each task.'}</p><button class="text-button" data-action="reminders">${icon('clock')}About task reminders ${icon('arrowright')}</button>${routineFacts()}</aside></div>${safetyNotice()}`;}
const HAZARDS=[
 {num:'01',icon:'sun',hrp:'hazard-space-radiation',title:'Space radiation',text:'Exposure beyond Earth’s protection can increase long term health risks. Operational dose monitoring and shielding belong to the vehicle and mission systems.',link:'What routine vitals can show',system:'immune'},
 {num:'02',icon:'brain',hrp:'hazard-isolation-and-confinement',title:'Isolation & confinement',text:'Limited space, separation from family, and changing schedules can affect sleep, mood, and teamwork. Track rest and wellbeing consistently.',link:'Explore mind & sleep',system:'behavioral'},
 {num:'03',icon:'signal',hrp:'hazard-distance-from-earth',title:'Distance from Earth',text:'Communication delays and limited resupply increase crew responsibility. Keep a useful record and use the approved onboard medical procedures.',link:'Prepare a health summary',action:'export-summary'},
 {num:'04',icon:'orbit',hrp:'hazard-gravity-fields',title:'Gravity fields',text:'Changing gravity affects fluid distribution, balance, bones, and muscles. Follow your individual exercise plan and report changes in function.',link:'Explore bones & muscles',system:'musculoskeletal'},
 {num:'05',icon:'wind',hrp:'hazard-hostile-closed-environments',title:'Hostile, closed environments',text:'Cabin air, microbes, noise, light, and temperature can affect health. Personal logs complement the vehicle’s dedicated environmental sensors.',link:'Explore the immune system',system:'immune'}
];
/* NASA's named risks and current studies, from the challenge resources (dist/hrp-reference.js, made by scripts/fetch-hrp.mjs). Summaries are NASA's own words. */
/* NASA risks tied to an indicator, body system or anatomy layer (dist/hrp-links.js). detail: 'action' adds NASA's "What can be done", 'summary' NASA's summary. */
function hrpRiskList(risks,detail=''){if(!risks.length)return '';const total=typeof HrpReference!=='undefined'?HrpReference.risks.length:'';return `<ul class="hrp-risk-list">${risks.map(r=>`<li><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(HrpLinks.name(r.title))}<span class="sr-only"> (NASA page, opens in a new tab)</span></a>${detail==='action'&&r.action?`<details><summary>What NASA does about it</summary><p>${esc(r.action)}</p>${hrpStudiesLine(r.id)}</details>`:detail==='summary'?`<p>${esc(r.summary)}</p>`:''}</li>`).join('')}</ul><p class="hrp-risk-note">ORBIT’s pairing with NASA’s named risks. <a href="#brief">See all ${total} risks</a></p>`;}
/* NASA's own link from its studies to a risk ("Top Risks Addressed" on each study page). */
function hrpStudiesLine(riskId){const list=HrpLinks.studiesFor(riskId);return list.length?`<p class="hrp-studies">NASA studies on this risk: ${list.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)}<span class="sr-only"> (opens in a new tab)</span></a>`).join(', ')}</p>`:'';}
/* A sentence quoted from a NASA or CSA page, with where it comes from. */
function hrpQuote(q){return q?`<blockquote class="hrp-quote"><p>“${esc(q.text)}”</p><footer><a href="${esc(q.url)}" target="_blank" rel="noopener noreferrer">${esc(q.title)}<span class="sr-only"> (opens in a new tab)</span></a> · ${esc(q.credit)}</footer></blockquote>`:'';}
/* CSA infographic areas and current CSA station experiments, in the CSA's words. names: experiment names only. */
function csaBlock({areas=[],experiments=[]},names=false){if(!areas.length&&!experiments.length)return '';const credit=typeof HrpReference!=='undefined'?HrpReference.csaCredit:'© Canadian Space Agency';return `${areas.map(a=>`<div class="hrp-csa-area"><b>${esc(a.title)}</b><p>${esc(a.text)}</p></div>`).join('')}${experiments.length?`<ul class="hrp-risk-list hrp-csa-list">${experiments.map(e=>`<li><a href="${esc(e.url)}" target="_blank" rel="noopener noreferrer">${esc(e.title.split(':')[0])}<span class="sr-only"> (CSA page, opens in a new tab)</span></a>${names?'':`<p>${esc(e.summary)}</p>`}</li>`).join('')}</ul>`:''}<p class="hrp-risk-note">${esc(credit)}. ${areas.length?'From <a href="'+esc(HrpReference.csaInfographic.url)+'" target="_blank" rel="noopener noreferrer">How does space affect the human body?</a>. ':''}Which experiments show here is ORBIT’s pairing.</p>`;}
const hrpGroups=list=>[...new Set(list.map(x=>x.group))].map(g=>[g,list.filter(x=>x.group===g)]);
/* A hazard card's NASA material: the risks it feeds (ORBIT's pairing, dist/hrp-links.js) and NASA's own hazard page text. */
function hazardNasa(id){if(typeof HrpLinks==='undefined')return '';const hz=HrpLinks.hazard(id),risks=HrpLinks.forHazard(id);if(!hz)return '';return `${risks.length?`<div class="hazard-risks"><span class="eyebrow">NASA RISKS IT FEEDS</span><p>${risks.map(r=>`<a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(HrpLinks.name(r.title))}<span class="sr-only"> (NASA page, opens in a new tab)</span></a>`).join(', ')}</p></div>`:''}${hz.text&&hz.text.length?`<details class="hazard-nasa"><summary>In NASA’s words</summary>${hz.text.map(t=>`<p>${esc(t)}</p>`).join('')}<a href="${esc(hz.url)}" target="_blank" rel="noopener noreferrer">Hazard: ${esc(hz.title)} on nasa.gov<span class="sr-only"> (opens in a new tab)</span> ↗</a></details>`:''}`;}
/* NASA's "About the Five Hazards": the hazards compound each other, and where NASA studies them. */
function briefCompound(){if(typeof HrpReference==='undefined'||!HrpReference.hazardsIntro)return '';const R=HrpReference;return `<section class="panel brief-hrp brief-compound" aria-labelledby="brief-compound-title"><div class="eyebrow">NASA HUMAN RESEARCH PROGRAM / ABOUT THE FIVE HAZARDS</div><h2 id="brief-compound-title">The hazards act together</h2>${R.hazardsIntro.map(t=>`<p class="brief-hrp-intro">${esc(t)}</p>`).join('')}<p class="brief-hrp-note">In NASA’s words, from <a href="${R.hazardsPage}" target="_blank" rel="noopener noreferrer">5 Hazards of Human Spaceflight</a>. The risks listed on each hazard card are ORBIT’s pairing of NASA’s pages; one risk can come from more than one hazard. NASA’s <a href="${R.risksPage}" target="_blank" rel="noopener noreferrer">risks page</a> adds that the effects of each risk vary with the destination: low Earth orbit, the Moon, or Mars.</p></section>`;}
function briefRisks(){if(typeof HrpReference==='undefined')return '';const R=HrpReference;return `<section class="panel brief-hrp" aria-labelledby="brief-risks-title"><div class="eyebrow">NASA HUMAN RESEARCH PROGRAM / ${R.risks.length} NAMED RISKS</div><h2 id="brief-risks-title">The risks behind the five hazards</h2><p class="brief-hrp-intro">NASA links ${R.risks.length} specific health risks to the five hazards. The summaries are NASA’s, from <a href="${R.risksPage}" target="_blank" rel="noopener noreferrer">Risks of Human Spaceflight</a>, retrieved ${R.fetched}. ORBIT does not measure these risks; it records the indicators you enter.</p>${hrpGroups(R.risks).map(([g,list])=>`<h3 class="brief-hrp-group">${esc(g.replace(/^Risks Involving /,''))} <span>${list.length}</span></h3><ul class="brief-hrp-list">${list.map(r=>`<li><a href="${r.url}" target="_blank" rel="noopener noreferrer">${esc(HrpLinks.name(r.title))}<span class="sr-only"> (NASA page, opens in a new tab)</span></a><p>${esc(r.summary)}</p>${hrpStudiesLine(r.id)}</li>`).join('')}</ul>`).join('')}<p class="brief-hrp-note">Ask about any of these risks in the <a href="#research">Evidence library</a>; the onboard library can answer from these NASA pages.</p></section>`;}
function briefStudies(){if(typeof HrpReference==='undefined')return '';const S=HrpReference.studies;return `<details class="panel brief-hrp brief-hrp-studies"><summary><h2>What NASA is studying now <span>${S.length} studies</span></h2></summary><p class="brief-hrp-intro">From <a href="${HrpReference.studiesPage}" target="_blank" rel="noopener noreferrer">Ongoing HRP Research in Space</a>, in NASA’s words.</p>${hrpGroups(S).map(([g,list])=>`<h3 class="brief-hrp-group">${esc(g)} <span>${list.length}</span></h3><ul class="brief-hrp-list">${list.map(s=>`<li><a href="${s.url}" target="_blank" rel="noopener noreferrer">${esc(s.title)}<span class="sr-only"> (NASA page, opens in a new tab)</span></a><p>${esc(s.summary)}</p></li>`).join('')}</ul>`).join('')}</details>`;}
function briefCsa(){if(typeof HrpReference==='undefined')return '';const R=HrpReference;return `<details class="panel brief-hrp brief-hrp-studies"><summary><h2>Canadian experiments on the station <span>${R.csaExperiments.length} current</span></h2></summary><p class="brief-hrp-intro">From the Canadian Space Agency’s <a href="${R.csaExperimentsPage}" target="_blank" rel="noopener noreferrer">Canadian experiments on the Station</a>, in the CSA’s words. ${esc(R.csaCredit)}.</p><ul class="brief-hrp-list">${R.csaExperiments.map(e=>`<li><a href="${esc(e.url)}" target="_blank" rel="noopener noreferrer">${esc(e.title)}<span class="sr-only"> (CSA page, opens in a new tab)</span></a><p>${esc(e.summary)}</p></li>`).join('')}</ul></details>`;}
function briefPage(){return `${pageHeading('Mission health brief','The science behind the monitoring.')}<section class="brief-hero"><div class="eyebrow">NASA HUMAN RESEARCH PROGRAM / REFERENCE BRIEF</div><h2>Five hazards.<br>One crew to look after.</h2><p>Long duration exploration changes how crews monitor their health. ORBIT brings personal indicators and daily routines into view, informed by NASA’s five human spaceflight hazards.</p><div class="mission-diagram"><span>${icon('globe')} EARTH</span><span>${icon('arrowright')} LOW EARTH ORBIT</span><span>${icon('arrowright')} LUNAR EXPLORATION</span><span>${icon('arrowright')} DEEP SPACE</span></div></section><div class="hazard-grid">${HAZARDS.map(h=>`<article class="panel hazard-card"><div class="hazard-top">${icon(h.icon)}<span>${h.num} / 05</span></div><h3>${h.title}</h3><p>${h.text}</p>${hazardNasa(h.hrp)}<button class="text-button" ${h.system?`data-body="${h.system}"`:`data-action="${h.action}"`}>${h.link} ${icon('arrowright')}</button></article>`).join('')}<article class="panel hazard-card resource-card"><div class="hazard-top">${icon('book')}<span>CREW REFERENCE</span></div><h3>Know your measurements.</h3><p>Good records start with consistent technique. Review the measurement guide before your next check-in.</p><button class="text-button" data-action="measurement-guide">Open measurement guide ${icon('arrowright')}</button></article></div>${briefCompound()}${briefRisks()}${briefStudies()}${briefCsa()}<section class="panel references"><h2>Sources & project context</h2><a class="reference-link" href="https://www.nasa.gov/hrp/hazards/" target="_blank" rel="noopener noreferrer"><span>5 Hazards of Human Spaceflight<small>NASA / HUMAN RESEARCH PROGRAM · CHALLENGE RESOURCE</small></span>${icon('external')}</a><a class="reference-link" href="https://www.nasa.gov/hrp/risks/" target="_blank" rel="noopener noreferrer"><span>Risks of Human Spaceflight<small>NASA / HUMAN RESEARCH PROGRAM · CHALLENGE RESOURCE</small></span>${icon('external')}</a><a class="reference-link" href="https://www.nasa.gov/hrp/ongoing-hrp-research/" target="_blank" rel="noopener noreferrer"><span>Ongoing HRP Research in Space<small>NASA / HUMAN RESEARCH PROGRAM · CHALLENGE RESOURCE</small></span>${icon('external')}</a><a class="reference-link" href="https://www.asc-csa.gc.ca/eng/iss/science/experiments.asp" target="_blank" rel="noopener noreferrer"><span>Canadian experiments on the Station<small>CANADIAN SPACE AGENCY · LINKED FROM A CHALLENGE RESOURCE</small></span>${icon('external')}</a><a class="reference-link" href="https://www.asc-csa.gc.ca/eng/multimedia/search/image/8056" target="_blank" rel="noopener noreferrer"><span>How does space affect the human body? (infographic)<small>CANADIAN SPACE AGENCY · LINKED FROM A CHALLENGE RESOURCE</small></span>${icon('external')}</a>${(typeof HrpReference!=='undefined'?HrpReference.csa:[]).map(a=>`<a class="reference-link" href="${a.url}" target="_blank" rel="noopener noreferrer"><span>${esc(a.title)}<small>CANADIAN SPACE AGENCY · CHALLENGE RESOURCE</small></span>${icon('external')}</a>`).join('')}<a class="reference-link" href="https://www.nasa.gov/humans-in-space/the-human-body-in-space/" target="_blank" rel="noopener noreferrer"><span>The Human Body in Space<small>NASA / HUMAN RESEARCH PROGRAM · PRIMARY REFERENCE</small></span>${icon('external')}</a><a class="reference-link" href="https://www.nasa.gov/hrp/" target="_blank" rel="noopener noreferrer"><span>NASA Human Research Program<small>RESEARCH, HUMAN HEALTH & PERFORMANCE</small></span>${icon('external')}</a><a class="reference-link" href="https://www.youtube.com/watch?v=RERG3gEmdC8" target="_blank" rel="noopener noreferrer"><span>2026 challenge: Create Health Monitoring Software for Astronauts<small>USER PROVIDED CHALLENGE VIDEO</small></span>${icon('external')}</a><p>ORBIT is an independent challenge prototype. NASA does not endorse or operate this application. The Earth photograph is credited to NASA. No clinical validation, live telemetry, radiation dosimetry, or diagnostic imaging is provided.</p></section>`;}
function render(){
 window.dispatchEvent(new Event('orbit:scope-check'));
 anatomyLastSelection=null;anatomyLastState=null;
 const p=currentPage(),main=$('#main');
 if(main.dataset.page!==p){const group=document.querySelector('.main-nav [data-nav="'+p+'"]')?.closest('details');if(group)group.open=true;}
 main.dataset.page=p;const scroll=window.scrollY;cleanupHealthInputs();disposeCrewViewer();
 main.innerHTML=(!storageAvailable?'<div class="save-warning">Local saving is unavailable. Export your data before leaving this page.</div>':'')+({'solar-system':solarSystemPage,model:neuralPage,status:missionStatusPage,wellbeing:missionWellbeingPage,exercise:missionExercisePage,risks:missionRisksPage,supplies:missionSuppliesPage,earthlink:missionLinkPage,research:missionResearchPage,skin:skinPage,care:carePage,overview:overviewPage,crew:crewDashboardPage,anatomy:anatomyLabPage,log:logPage,trends:trendsPage,systems:systemsPage,routine:routinePage,brief:briefPage}[p])();
 $$('.main-nav a').forEach(a=>{a.classList.toggle('active',a.dataset.nav===p);if(a.dataset.nav===p)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 $('#header-page').textContent=PAGE_NAMES[p];$('#data-mode').textContent=state.mode==='demo'?'DEMO MISSION':'MY HEALTH LOG';$('#routine-count').textContent=checks().length+'/5';$('#rail-environment').textContent=state.settings.environment.toUpperCase();document.title=`${PAGE_NAMES[p]} | ORBIT`;
 if(p==='systems')attachSpaceAnimations();if(p==='solar-system')attachSolarSystem();syncCrewHeader();hydrateIcons(main);bindChart();if(p==='crew')attachCrewViewer();if(p==='anatomy')attachAnatomyLab();if(p==='care')attachCarePage();if(p==='model')attachNeuralPage();if(p==='earthlink')attachMissionLink();if(p==='research')attachOnboardAssistant();if(p==='skin')attachSkinPage();window.scrollTo(0,scroll);window.dispatchEvent(new Event('orbit:context-change'));
}
function bindChart(){const tip=$('.chart-tooltip');if(!tip)return;$$('[data-point]').forEach(el=>{el.addEventListener('pointerenter',()=>{const d=chartData()[+el.dataset.point];tip.textContent=`${dayLabel(d.at)} · ${formatNum(d[chartMetric],META[chartMetric].digits)} ${META[chartMetric].unit}`;tip.classList.add('visible');});el.addEventListener('pointerleave',()=>tip.classList.remove('visible'));});}
function modal(title,subtitle,body,footer=''){disposeInputModal();const d=$('#modal');d.innerHTML=`<div class="modal-head"><div><h2 id="modal-title">${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button class="icon-button" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-foot">${footer}</div>`:''}`;hydrateIcons(d);if(!d.open)d.showModal();d.scrollTop=0;window.dispatchEvent(new Event('orbit:modal-open'));}
function announceFormSaved(form,node,persistent=storageAvailable){window.dispatchEvent(new CustomEvent('orbit:form-saved',{detail:{form,save_id:node?.dataset.assistantSaveId||'',persistent,workspace:state.mode,crewId:activeCrewId()}}));}
function closeModal(){disposeInputModal();$('#modal').close();}
function logModal(prefill={}){
 const fields=[['hr','Resting heart rate','bpm',0,350,1],['temp','Body temperature','°C',20,50,.1],['sleep','Sleep duration','hrs',0,24,.1],['glucose','Blood glucose','mg/dL',0,1500,1]];
 const f=(k,label,unit,min,max,step)=>`<label class="field"><span>${label} <small>(optional)</small></span><div class="input-with-unit"><input class="field-input" name="${k}" type="number" inputmode="decimal" min="${min}" max="${max}" step="${step}" placeholder="—"><em>${unit}</em></div></label>`;
 modal('Log a health check',state.mode==='demo'?'Demo workspace · Entries stay separate from your personal record.':'Personal workspace · Saved only in this browser.',`<p class="form-help">Enter the indicators you measured. Leave the others blank. Use the same equipment and technique where possible. <button class="instruction-link" data-action="care-inline-guide" aria-expanded="false" aria-controls="log-care-guide">Measurement guide</button></p>${careInlineGuideMarkup()}<form id="health-form"><div class="form-grid">${crewFieldMarkup()}<label class="field full"><span>Measurement date & time <small>(local device time)</small></span><input class="field-input" type="datetime-local" name="at" required value="${localInput()}" max="${localInput()}"></label><div class="form-section-label">PHYSIOLOGICAL INDICATORS</div>${f(...fields[0])}<label class="field"><span>Blood pressure <small>(mmHg, optional)</small></span><div class="bp-pair"><input class="field-input" name="sys" type="number" inputmode="numeric" min="0" max="350" placeholder="Systolic" aria-label="Systolic blood pressure"><b>/</b><input class="field-input" name="dia" type="number" inputmode="numeric" min="0" max="250" placeholder="Diastolic" aria-label="Diastolic blood pressure"></div></label>${f(...fields[1])}${f(...fields[2])}${f(...fields[3])}<label class="field"><span>Glucose measurement context</span><select class="field-input" name="glucoseContext"><option>Not specified</option><option>Fasting</option><option>Before meal</option><option>After meal</option></select></label>${extraInputFields(f)}<div class="form-section-label">WELLBEING & OBSERVATIONS</div><div class="field full"><span>Mood <small>(optional personal check-in)</small></span><div class="mood-picker" role="group" aria-label="Mood">${Object.entries(moodNames).map(([n,t])=>`<label class="mood-option"><input type="radio" name="mood" value="${n}"><span>${n}<small>${t}</small></span></label>`).join('')}</div></div><label class="field full"><span>Symptoms & notes <small>(optional)</small></span><textarea class="field-input" name="notes" maxlength="2000" placeholder="Include symptom onset, measurement conditions, or changes to your routine."></textarea></label></div><div class="form-error" role="alert" id="form-error"></div></form><div class="notice" style="margin-top:18px">${icon('info')}<p>Input limits help catch entry errors; they are not clinical reference ranges. A saved reading does not mean you are medically well.</p></div>`,`${button('Cancel','close-modal')}<button class="button primary" type="submit" form="health-form">${icon('check')}Save health check</button>`);
 const form=$('#health-form');form.dataset.source=prefill.source||'Manual entry';for(const key of [...Object.keys(InputLogic.fields),'at','notes'])if(prefill[key]!==undefined&&form.elements.namedItem(key))form.elements.namedItem(key).value=key==='at'?localInput(new Date(prefill[key])):String(prefill[key]);
 form.addEventListener('submit',saveHealthCheck);
}
function saveHealthCheck(event){
 event.preventDefault();const f=new FormData(event.target),record={source:event.target.dataset.source||'Manual entry',crewId:f.get('crewId')||activeCrewId(),id:crypto.randomUUID?.()||'entry-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,10),at:new Date(f.get('at')).toISOString(),notes:f.get('notes').trim(),glucoseContext:f.get('glucoseContext')};
 for(const k of Object.keys(InputLogic.fields)){const v=f.get(k);if(v!==null&&String(v).trim()!=='')record[k]=Number(v);}
 const fail=msg=>{$('#form-error').textContent=msg;};
 if(!crewProfiles().some(p=>p.id===record.crewId))return fail('Select a valid crew member.');
 if(Date.parse(record.at)>Date.now()+60000)return fail('Choose the current time or an earlier measurement time.');
 if((Number.isFinite(record.sys))!==Number.isFinite(record.dia))return fail('Enter both systolic and diastolic blood pressure, or leave both blank.');
 if(Number.isFinite(record.sys)&&record.sys<=record.dia)return fail('Systolic pressure must be greater than diastolic pressure. Check the values.');
 if(!Object.keys(META).some(k=>Number.isFinite(record[k]))&&!record.notes)return fail('Add at least one indicator or an observation.');
 if(!Number.isFinite(record.glucose))delete record.glucoseContext;
 db().activeCrewId=record.crewId;db().entries.push(record);if(new Date(record.at).toLocaleDateString('en-CA')===todayKey()){const s=new Set(checks());s.add('vitals');if(record.mood)s.add('mood');db().checks[crewCheckKey()]=[...s];}
 persist();announceFormSaved('health-form',event.target);closeModal();render();toast(storageAvailable?(state.mode==='demo'?'Demo health check saved.':'Health check saved on this device.'):'Reading added for this session. Export it before closing the page.');
}
function settingsModal(){modal('Mission settings','Your workspace, data, and daily rest target.',`<div class="settings-modes"><button class="mode-option ${state.mode==='demo'?'active':''}" data-mode="demo"><div class="eyebrow">SIMULATION WORKSPACE</div><h3>Explore demo data</h3><p>A sample crew record with 28 days of indicators.</p></button><button class="mode-option ${state.mode==='personal'?'active':''}" data-mode="personal"><div class="eyebrow">PERSONAL WORKSPACE</div><h3>Use my own data</h3><p>A separate record. ${state.data.personal.entries.length} entries saved locally.</p></button></div><form id="settings-form"><div class="form-grid"><label class="field full"><span>Mission name</span><input class="field-input" name="mission" value="${esc(state.settings.mission)}" maxlength="40" required></label><label class="field"><span>Mission environment</span><select class="field-input" name="environment">${['Lunar transit','Space station','Lunar surface habitat','Mars transit','Mars surface habitat','Surface rover'].map(t=>`<option ${state.settings.environment===t?'selected':''}>${t}</option>`).join('')}</select></label><label class="field"><span>Planned sleep target <small>(hrs)</small></span><input class="field-input" name="sleepTarget" type="number" min="4" max="12" step="0.5" required value="${state.settings.sleepTarget}"></label></div><p class="form-help" style="margin:15px 0 0">The sleep target is a planning preference. Use the rest period set by your medical team.</p></form><div class="settings-divider"></div><div class="prose"><h3>Data controls</h3><p>Data stays in this browser. No application accounts, medical service connection, or cloud synchronization are included. Camera and compatible heart rate monitor inputs work only when you choose to use them.</p><div style="display:flex;gap:10px;margin-top:14px;flex-wrap:wrap">${button('Export CSV','export-csv','small','download')}${button('Clear current workspace','clear-data','danger small','trash')}</div></div>`,`${button('Close','close-modal')}<button class="button primary" type="submit" form="settings-form">Save settings</button>`);$('#settings-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);state.settings={...state.settings,mission:f.get('mission').trim()||'Exploration 01',environment:f.get('environment'),sleepTarget:Number(f.get('sleepTarget'))};persist();announceFormSaved('settings-form',e.target);closeModal();render();toast('Mission settings saved.');});}
function setMode(mode){if(!['demo','personal'].includes(mode))return;state.mode=mode;initCrewData();persist();closeModal();render();toast(mode==='demo'?'Demo workspace selected.':'Your personal workspace is ready.');}
function download(name,content,type){const b=new Blob([content],{type}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download=name;a.hidden=true;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),60000);}
function csvCell(v){let s=String(v??'');if(/^[\s]*[=+@\-]|^[\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';}
function exportCSV(){const all=entries();if(!all.length){toast('No records to export. Add a health check first.');return;}const keys=['at',...Object.keys(InputLogic.fields),'glucoseContext','source','notes'];const headers=['Crew ID','Crew name','Timestamp (ISO 8601)',...Object.entries(InputLogic.fields).map(([key,rule])=>(META[key]?.label||'Diastolic pressure')+' ('+rule.unit+')'),'Glucose context','Input source','Notes'];const rows=[headers,...all.map(record=>[record.crewId||'crew-01',activeCrew().name,...keys.map(key=>record[key]??'')])];download(`orbit-${state.mode}-health-${todayKey()}.csv`,'\uFEFF'+rows.map(row=>row.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8');toast('Health records exported as CSV.');}

function exportSummary(){const all=entries();if(!all.length){toast('No records to export. Add a health check first.');return;}const since=Date.now()-7*86400000,week=all.filter(e=>Date.parse(e.at)>=since);let t=`ORBIT | CREW HEALTH SUMMARY\n${state.mode==='demo'?'SIMULATED DATA — DEMO WORKSPACE':'PERSONAL RECORD — SELF REPORTED'}\nCrew: ${activeCrew().name} (${activeCrewId()})\nMission: ${state.settings.mission}\nEnvironment: ${state.settings.environment}\nExported: ${new Date().toISOString()}\nAll timestamps below use the device’s local time.\n\nLATEST RECORDED INDICATORS\n`;
 for(const [k,m]of Object.entries(META)){const e=latest(k);t+=`${m.label}: ${e?`${formatNum(e[k],m.digits)} ${m.unit} (${new Date(e.at).toLocaleString()})`:'Not recorded'}\n`;}
 t+=`\nPAST 7 DAYS: ${week.length} health checks\n`;
 week.forEach(e=>{t+=`\n${new Date(e.at).toLocaleString()}\n`;for(const [k,m]of Object.entries(META)){if(Number.isFinite(e[k]))t+=`  ${m.label}: ${formatNum(e[k],m.digits)} ${m.unit}${k==='glucose'?' ('+(e.glucoseContext||'context not specified')+')':''}\n`;}if(Number.isFinite(e.dia))t+=`  Diastolic pressure: ${e.dia} mmHg\n`;if(e.notes)t+=`  Notes: ${e.notes}\n`;});
 t+=`\nCONDITION NOTES\n${activeCrew().conditions.length?activeCrew().conditions.map(c=>`${c.title} | ${c.status} | ${CREW_REGIONS[c.region]||'General'} | ${c.source} | ${c.date}\n${c.notes||''}`).join('\n\n'):'No condition notes recorded.'}\n`;
 t+=`\nTODAY’S SELF REPORTED ROUTINE\n${ROUTINES.map(r=>`[${checks().includes(r.id)?'x':' '}] ${r.title}`).join('\n')}\n\nLIMITATIONS\nIndependent research prototype. Not clinically validated. No diagnosis, fitness determination, or medication recommendation. Records are manually entered and are not verified. Use approved mission medical procedures. This export has not been transmitted to any medical service.\n`;
 t+=OrbitNeural.summary(OrbitNeural.getCurrentAssessment());
 download(`orbit-${state.mode}-summary-${todayKey()}.txt`,t,'text/plain;charset=utf-8');toast('Health summary exported. Nothing has been transmitted.');}
function entryModal(id){const e=entries().find(e=>e.id===id);if(!e)return;modal('Health check record',new Date(e.at).toLocaleString()+' · '+(state.mode==='demo'?'Sample workspace':'Personal record'),`<div class="review-entry-grid">${Object.entries(META).map(([k,m])=>`<div class="review-entry-item"><span>${m.label.toUpperCase()}</span><strong>${hiddenCell(e,k)||formatNum(e[k],m.digits)+' '+m.unit}</strong>${k==='sys'?`<small>Diastolic: ${formatNum(e.dia)} mmHg</small>`:''}${k==='glucose'&&e.glucoseContext?`<small>${esc(e.glucoseContext)}</small>`:''}</div>`).join('')}</div><div class="prose" style="margin-top:24px"><h3>Symptoms & notes</h3><p class="review-notes">${hiddenCell(e,'notes')?'Hidden. Only this crew member, the crew leader and the medical officer can read check-in notes.':esc(e.notes)||'No observations recorded.'}</p></div>`,button('Close','close-modal'));}
function deleteModal(id){const e=db().entries.find(e=>e.id===id);if(!e)return;modal('Delete health record?',new Date(e.at).toLocaleString(),'<p class="form-help">This removes the selected entry from this browser. Export a copy first if you need to keep it.</p>',`${button('Keep record','close-modal')}<button class="button danger" data-confirm-delete="${esc(id)}">Delete record</button>`);}
function clearModal(){modal('Clear this workspace?',state.mode==='demo'?'Demo data only':'Personal health records',`<div class="delete-confirm"><p>This removes ${db().entries.length} health records , all condition notes, guided assessments, care plans, image observations, emergency checklists, mission risk readings, supplies, workouts, simulated Earth link messages, skin checks, wounds, and daily checklist history from the ${state.mode==='demo'?'demo':'personal'} workspace. It leaves the other workspace intact. Export a copy first if you need one.</p></div>`,`${button('Keep my data','close-modal')}<button class="button danger" data-action="confirm-clear">Clear workspace</button>`);}
const GUIDES={
 'sleep-guide':{title:'Protect your rest period',sub:'Crew reference / Sleep & alertness',body:'<h3>Review the context</h3><p>Record sleep duration alongside schedule changes, workload, noise, and how rested you feel. A short night is a prompt to review your routine; it does not diagnose a sleep disorder.</p><h3>Plan your next rest period</h3><p>Follow the mission light and sleep schedule. Protect a consistent sleep opportunity and review persistent fatigue with your crew medical officer, especially before safety critical tasks.</p><h3>How ORBIT flags this</h3><p>The latest sleep duration appears as “Review” when it falls below your planned sleep target. That target is an adjustable planning preference, not a clinical threshold.</p>'},
 'mood-guide':{title:'Make time for a check-in',sub:'Crew reference / Behavioral health',body:'<h3>Keep an honest record</h3><p>The crew member, the crew leader and the medical officer can see mood entries; the rest of the crew sees only a neutral support prompt. It does not provide a diagnosis or a validated screening result. Note changes in sleep, motivation, concentration, or how daily tasks feel.</p><h3>Use your support channels</h3><p>Follow your private medical communication plan and check in with your crew medical officer about persistent changes. If you feel unable to keep yourself or others safe, tell a crew member and activate your onboard emergency medical procedure immediately.</p><h3>How ORBIT flags this</h3><p>A mood entry of 1 or 2 prompts a supportive check-in reminder. This simple product rule has no established clinical validity.</p>'},
 'measurement-guide':{title:'Take a consistent measurement',sub:'Crew reference / Manual health checks',body:'<h3>Use the mission procedure</h3><p>Use approved equipment and your trained measurement technique. Record the time and context. The instructions below help document a measurement and do not replace the device instructions or mission protocol.</p><h3>Heart rate & blood pressure</h3><p>Record resting readings under similar conditions. Note exercise, symptoms, posture or body restraint, and measurement method. Follow the approved cuff size and placement instructions.</p><h3>Temperature</h3><p>Use the same device and measurement site. Document the method in your notes because different sites and devices can yield different readings.</p><h3>Blood glucose</h3><p>Only test when your medical plan calls for it. Follow your meter procedure and record whether the reading came before a meal, after a meal, or during fasting. Use your prescribed action limits.</p><h3>Sleep & mood</h3><p>Record the hours you actually slept and your current mood. Add useful context, such as a schedule change or unusual workload.</p><h3>Unexpected readings</h3><p>Follow the device and mission procedure for checking an unexpected result. Document symptoms and contact the crew medical officer when the result meets your individual action limits or concerns you.</p>'},
 emergency:{title:'Urgent crew response',sub:'Use your approved mission emergency procedures.',body:'<h3 class="emergency-heading">Symptoms take priority over the dashboard</h3><p>Severe chest pain, serious breathing difficulty, loss of consciousness, signs of stroke, uncontrolled bleeding, or any immediate threat to safety require an immediate crew response.</p><ol><li>Alert the crew and crew medical officer immediately.</li><li>Activate the approved onboard medical emergency procedure for the situation.</li><li>Contact ground medical support through the mission emergency channel when available. Communication delays must not postpone trained immediate care.</li></ol><p>ORBIT cannot detect emergencies, contact medical support, or guide clinical treatment. Do not use a dashboard reading to rule out a serious problem.</p>'},
 reminders:{title:'Your daily task reminders',sub:'Routine support / Local device time',body:'<h3>During an app session</h3><p>The checklist follows the individual schedule entered in Health assessment, with illustrative times until you change them. It starts fresh at midnight in the device’s local time and preserves previous completion history in browser storage.</p><h3>Outside the app</h3><p>Enable in-session reminders and edit each crew member’s schedule under Health assessment → Mission readiness → Edit individual plan. ORBIT checks due tasks while the app is open and visible. It does not send background notifications. Use the mission scheduling system or a device alarm for reliable reminders, and follow your actual medical and exercise schedule.</p>'},
 about:{title:'About ORBIT',sub:'Crew health monitoring / Research prototype',body:'<h3>Built for the challenge</h3><p>ORBIT organizes manually entered health indicators, personal trends, daily routines, and crew condition notes for an exploration mission scenario. The Astronauts dashboard links those records to generic reference anatomy, not patient specific scans. It is an independent prototype and has no NASA affiliation or endorsement.</p><h3>Your data</h3><p>Records and settings stay in this browser’s local storage. The optional Crew assistant sends voice or text, page context, and selected reference anatomy to ElevenLabs and its model provider after you start a session. Health summaries and original images require a separate review and explicit sharing action. These shared copies may be retained under your ElevenLabs settings; ending a session does not delete them. No report is sent to a medical team. An optional compatible Bluetooth heart rate monitor can supply a reading after you choose a device. Uploaded and captured image observations stay in this browser’s image database, and the crew archive can back them up. Guided assessments and individual plans also stay in this browser. The optional offline package caches application and anatomy files, not a separate medical backup. Browser storage is not a clinical record system or an encrypted medical vault. Shared device users may be able to access it. Export a copy before clearing browser storage.</p><h3>Demo & personal workspaces</h3><p>Demo readings are synthetic. You can explore and edit the demo without affecting a separate personal record. Switch workspaces in Mission settings.</p><h3>Clinical limits</h3><p>No clinical validation, diagnosis, medication advice, or fitness for duty assessment is provided. Sleep and mood reminders use simple disclosed product rules, not validated medical triage. The assessment workspace can compare readings with optional, manually entered individual review bands. These are not NASA limits, clinical classifications, or proof of medical fitness. Emergency guidance and guided checklists are educational prompts; onboard procedures govern care. Trend alerts use simple disclosed product rules. Mission risk and supply figures come only from entered records; projections are straight lines, not medical predictions.</p><h3>Sources & image credit</h3><p>Educational content summarizes <a href="https://www.nasa.gov/humans-in-space/the-human-body-in-space/" target="_blank" rel="noopener noreferrer">NASA’s Human Research Program overview of the human body in space</a>. The aurora photograph, taken from the International Space Station, is credited to NASA. Charts reflect only manually entered or synthetic data.</p>'}
};
function guideModal(name){const g=GUIDES[name];if(!g)return;modal(g.title,g.sub,`<div class="prose">${g.body}</div>`,button('Close','close-modal'));}
function navClose(){document.body.classList.remove('nav-open');$('.menu-toggle').setAttribute('aria-expanded','false');}
document.addEventListener('click',e=>{
 const t=e.target.closest('button,a');if(!t)return;if(handleHealthInputControl(t))return;if(handleMissionControl(t))return;if(handleSkinControl(t))return;if(handleCareControl(t))return;if(handleAnatomyControl(t))return;if(handleCrewControl(t))return;
 if(t.dataset.action){const a=t.dataset.action;if(a==='neural-refresh'){if(currentPage()==='model')neuralRenderResult();}else if(a==='log')logModal();else if(a==='close-modal')closeModal();else if(a==='settings')settingsModal();else if(a==='personal')setMode('personal');else if(a==='export-csv')exportCSV();else if(a==='export-summary')exportSummary();else if(a==='clear-data')clearModal();else if(a==='confirm-clear'){clearWorkspaceWithImages();}else if(a==='more-log'){logLimit+=20;render();}else if(a==='menu'){document.body.classList.toggle('nav-open');$('.menu-toggle').setAttribute('aria-expanded',document.body.classList.contains('nav-open'));}else if(GUIDES[a])guideModal(a);}
 if(t.dataset.chart){chartMetric=t.dataset.chart;render();}
 if(t.dataset.range){chartRange=+t.dataset.range;render();}
 if(t.dataset.body){systemSelected=t.dataset.body;if(currentPage()==='systems')render();else location.hash='systems';}
 if(t.dataset.system){systemSelected=t.dataset.system;render();}
 if(t.dataset.check)toggleCheck(t.dataset.check);
 if(t.dataset.facts)factsModal();
 if(t.dataset.mode)setMode(t.dataset.mode);
 if(t.dataset.entry)entryModal(t.dataset.entry);
 if(t.dataset.delete)deleteModal(t.dataset.delete);
 if(t.dataset.confirmDelete){db().entries=db().entries.filter(r=>r.id!==t.dataset.confirmDelete);persist();closeModal();render();toast('Health record deleted.');}
 if(t.matches('.main-nav a'))navClose();
});
document.addEventListener('change',e=>{if(e.target.id==='trend-metric'){chartMetric=e.target.value;render();}});
document.addEventListener('input',e=>{if(e.target.id==='log-search'){const pos=e.target.selectionStart;filterQuery=e.target.value;render();const input=$('#log-search');input.focus();input.setSelectionRange(pos,pos);}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
$('.mobile-scrim').addEventListener('click',navClose);
window.addEventListener('hashchange',()=>{navClose();render();window.scrollTo(0,0);});
document.addEventListener('keydown',e=>{if(e.key==='Escape')navClose();});
let lastDay=todayKey();setInterval(()=>{if(todayKey()!==lastDay){lastDay=todayKey();render();}careTick();},30000);
OrbitNeuralLogic.validateModel(OrbitNeuralModel);
OrbitNeural.connect(() => OrbitNeural.assessRecords({records:entries(),baseline:activeCrew().neuralBaseline,model:OrbitNeuralModel,allowed:canSeeWellbeing(),workspace:state.mode}));
hydrateIcons();persist();render();if(storageNotice)toast(storageNotice);
